// Generates src/design/tokens.generated.ts from orbin-pos-spec.json → designSystem.
// This generated file is the ONLY place where raw hex colors may appear (ESLint enforces it).
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const specPath = resolve(here, '../../orbin-pos-spec.json');
const outPath = resolve(here, '../src/design/tokens.generated.ts');

const spec = JSON.parse(readFileSync(specPath, 'utf8'));
const ds = spec.designSystem;

const banner = `// AUTO-GENERATED by scripts/generate-tokens.mjs from orbin-pos-spec.json (designSystem).
// Do not edit by hand. Run \`npm run tokens:generate\` after changing the spec.
// This is the only file in the frontend allowed to contain raw hex colors.
`;

const body = `
export const colors = ${JSON.stringify(ds.colorTokens, null, 2)} as const;

export const typography = ${JSON.stringify(ds.typography, null, 2)} as const;

export const radius = ${JSON.stringify(ds.radius, null, 2)} as const;

export const spacingBasePx = ${ds.spacingBasePx};

export const shadows = ${JSON.stringify(ds.shadows, null, 2)} as const;

export const motion = ${JSON.stringify(ds.motion, null, 2)} as const;

export const mirrorShine = ${JSON.stringify(ds.mirrorShine, null, 2)} as const;

export const componentSpecs = ${JSON.stringify(ds.components, null, 2)} as const;

export const brand = ${JSON.stringify(spec.brand, null, 2)} as const;
`;

writeFileSync(outPath, banner + body);
console.log(`tokens written → ${outPath}`);
